import type { Faq, SpecValue, MachineConfiguration } from "@/lib/types";

/**
 * RIPPA equipment lineup — specs transcribed from the official RIPPA spec-sheet brochures (2025/26 editions).
 * Every model except the R13 PRO is offered with an open canopy or an enclosed cab. Prices are the dealer's
 * current listing prices (CAD) and can be edited in /admin. Fields left "—" in the brochure are omitted.
 * Notes flag values that the brochure itself prints inconsistently.
 */

type SG = SpecValue["group"];
const s = (label: string, value: string, imperial: string, group: SG, icon?: SpecValue["icon"], highlight = false): SpecValue => ({ label, value, imperial, group, icon: icon ?? "generic", highlight });

interface Feat { eyebrow?: string; title: string; text: string; image?: string }
export interface LineupModel {
  slug: string; modelName: string; category: "excavators" | "skid-steers" | "loaders" | "track-dumpers"; series: string; badge?: string;
  shortDescription: string; longDescription: string; certifications: string[]; warranty: string;
  configurations: MachineConfiguration[]; specs: SpecValue[]; features: Feat[]; standardEquipment: string[]; applications: string[]; faqs: Faq[];
  images: { key: string; alt: string }[]; brochure: string; builderEnabled: boolean; featured: boolean; sortOrder: number; targetUsers?: string; noiseLevel?: string; indoorUse?: boolean;
}

const cabPair = (id: string, engine: string, hp: string, weightCanopy: string, weightCab: string, priceCanopy?: number, priceCab?: number): MachineConfiguration[] => [
  { id: `${id}-canopy`, label: "Open canopy", engine, horsepower: hp, operatingWeight: weightCanopy, price: priceCanopy },
  { id: `${id}-cab`, label: "Enclosed cab", engine, horsepower: hp, operatingWeight: weightCab, price: priceCab },
];

const excFaqs = (m: string, width: string, weight: string, gate: string): Faq[] => [
  { question: `Will the ${m} fit through my gate?`, answer: `Minimum transport width is ${width}. ${gate}` },
  { question: "Open canopy or enclosed cab?", answer: "The canopy version is lighter, cheaper and easier to trailer. The enclosed cab adds glass, a door, heater/wiper and keeps you working in rain and Ontario winters. Both share the same engine, hydraulics and attachments." },
  { question: "Can I tow it behind my pickup?", answer: `Operating weight is ${weight} plus trailer and attachments. Check your truck's rated towing capacity and use an equipment trailer with brakes. We also deliver anywhere in Ontario.` },
  { question: "What comes standard?", answer: "Digging bucket, dozer blade, auxiliary hydraulic lines and quick coupler. Thumbs, extra buckets, augers, rakes and breakers are optional and listed under Attachments with sizes that fit." },
  { question: "What warranty and support do I get?", answer: "Two-year warranty backed by our service department, genuine RIPPA and Kubota parts, dealer pre-delivery inspection, and optional extended coverage in the builder." },
];

